create temp table reserved(label text primary key,id uuid,storage_path text,actor uuid);
grant all on reserved to authenticated,service_role;
create function pg_temp.reserve_fixture(p_ticket uuid,p_name text default 'note.txt',p_mime text default 'text/plain',p_size integer default 4,p_org uuid default 'f8200000-0000-4000-8000-000000000001')
returns table(id uuid,storage_path text) language sql as $$
 select * from public.reserve_ticket_attachment(p_org,p_ticket,(select revision from public.tickets where tickets.id=p_ticket),
 (select access_revision::bigint from public.ticket_context(p_org)),(select scope_revision from public.ticket_context(p_org)),p_name,p_mime,p_size);
$$;

select extensions.ok((select not public and file_size_limit=10485760 from storage.buckets where id='attachment-quarantine'),'Quarantine is private and bounded');
select extensions.ok(not has_function_privilege('anon','public.attachment_transfer_metadata(uuid,uuid,text,uuid,uuid)','execute'),'Anonymous has no transfer metadata grant');
select extensions.ok(not has_function_privilege('authenticated','public.attachment_transfer_metadata(uuid,uuid,text,uuid,uuid)','execute'),'Application users have no transfer metadata grant');
select extensions.ok(has_function_privilege('service_role','public.attachment_transfer_metadata(uuid,uuid,text,uuid,uuid)','execute'),'Trusted transfer grant exists');
select extensions.ok(not has_table_privilege('service_role','public.attachments','select'),'Service still lacks a broad attachment SELECT grant');
select extensions.ok(not has_function_privilege('authenticated','public.attachment_cleanup_batch(integer)','execute'),'Users cannot execute cleanup');
reset role;set local role authenticated;set local request.jwt.claims='{"sub":"f8100000-0000-4000-8000-000000000007","role":"authenticated"}';
insert into reserved select 'transfer',f.id,f.storage_path,'f8100000-0000-4000-8000-000000000007' from pg_temp.reserve_fixture('f8400000-0000-4000-8000-000000000001') f;
select extensions.throws_ok('select public.attachment_cleanup_batch(10)','42501',null,'Authenticated cleanup denied');
select extensions.throws_ok('select public.attachment_transfer_metadata(''f8200000-0000-4000-8000-000000000001'',''f8400000-0000-4000-8000-000000000001'',''ticket'',(select id from reserved where label=''transfer''),''f8100000-0000-4000-8000-000000000007'')','42501',null,'Authenticated metadata denied');
reset role;set local role service_role;set local request.jwt.claims='{"role":"service_role"}';
select extensions.is(public.attachment_transfer_metadata('f8200000-0000-4000-8000-000000000001','f8400000-0000-4000-8000-000000000001','ticket',(select id from reserved where label='transfer'),'f8100000-0000-4000-8000-000000000007')->>'state','uploading','Trusted handler can inspect its uploader reservation');
select extensions.ok(public.attachment_transfer_metadata('f8200000-0000-4000-8000-000000000001','f8400000-0000-4000-8000-000000000001','ticket',(select id from reserved where label='transfer'),'f8100000-0000-4000-8000-000000000008') is null,'Transfer binds uploader');
select extensions.ok(public.attachment_transfer_metadata('f8200000-0000-4000-8000-000000000002','f8400000-0000-4000-8000-000000000001','ticket',(select id from reserved where label='transfer'),'f8100000-0000-4000-8000-000000000007') is null,'Transfer binds organization');
select extensions.ok(public.attachment_transfer_metadata('f8200000-0000-4000-8000-000000000001','f8400000-0000-4000-8000-000000000002','ticket',(select id from reserved where label='transfer'),'f8100000-0000-4000-8000-000000000007') is null,'Transfer binds parent');
select extensions.ok(public.attachment_transfer_metadata('f8200000-0000-4000-8000-000000000001','f8400000-0000-4000-8000-000000000001','proposal',(select id from reserved where label='transfer'),'f8100000-0000-4000-8000-000000000007') is null,'Transfer binds parent kind');
select extensions.throws_ok('select public.attachment_cleanup_batch(0)','22023',null,'Cleanup rejects zero batch');
select extensions.throws_ok('select public.attachment_cleanup_batch(1001)','22023',null,'Cleanup bounds batch');
select extensions.ok(public.complete_ticket_attachment((select id from reserved where label='transfer'),'f8100000-0000-4000-8000-000000000007',repeat('a',64)) is not null,'Existing trusted completion keeps its business permission checks');
reset role;
insert into storage.objects(id,bucket_id,name,created_at) values('f9700000-0000-4000-8000-000000000001','attachment-quarantine','f9700000-0000-4000-8000-000000000001',clock_timestamp()-interval '25 hours');
insert into storage.objects(id,bucket_id,name,created_at) select 'f9700000-0000-4000-8000-000000000002','ticket-attachments',storage_path,clock_timestamp()-interval '25 hours' from reserved where label='transfer';
insert into storage.objects(id,bucket_id,name,created_at) values('f9700000-0000-4000-8000-000000000003','attachment-quarantine','f9700000-0000-4000-8000-000000000003',clock_timestamp()-interval '1 hour');
create temp table cleanup_result(data jsonb);grant all on cleanup_result to service_role;
set local role service_role;set local request.jwt.claims='{"role":"service_role"}';
insert into cleanup_result select public.attachment_cleanup_batch(1000);
select extensions.ok(exists(select 1 from cleanup_result,jsonb_array_elements(data) item where item->>'path'='f9700000-0000-4000-8000-000000000001'),'Long-expired quarantine is cleanup eligible');
select extensions.ok(not exists(select 1 from cleanup_result,jsonb_array_elements(data) item where item->>'path'='f9700000-0000-4000-8000-000000000003'),'Live capability bytes stay out of cleanup');
select extensions.ok(not exists(select 1 from cleanup_result,jsonb_array_elements(data) item where item->>'bucket'='ticket-attachments' and item->>'path'=(select storage_path from reserved where label='transfer')),'Ready permanent file is never cleanup eligible');
select extensions.is(public.attachment_transfer_metadata('f8200000-0000-4000-8000-000000000001','f8400000-0000-4000-8000-000000000001','ticket',(select id from reserved where label='transfer'),'f8100000-0000-4000-8000-000000000007')->>'state','ready','Ready metadata survives cleanup');
select extensions.is((public.attachment_transfer_metadata('f8200000-0000-4000-8000-000000000001','f8400000-0000-4000-8000-000000000001','ticket',(select id from reserved where label='transfer'),'f8100000-0000-4000-8000-000000000007')->>'sha256'),repeat('a',64),'Verified checksum stays immutable');
select * from extensions.finish();rollback;
